refused_program.body:
set -e

if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git merge --no-commit --no-ff --no-edit {upstream_remote}/{upstream_branch} || true
fi

if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  echo "expected a merge with {upstream_remote}/{upstream_branch}" >&2
  exit 1
fi

if git diff --name-only --diff-filter=U | grep -vqx 'deps.lock'; then
  echo "unexpected merge conflicts" >&2
  exit 1
fi

base=$(git merge-base HEAD {upstream_remote}/{upstream_branch})
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

git show "$base:deps.lock" > "$tmp/base.lock"
git show "HEAD:deps.lock" > "$tmp/ours.lock"
git show "{upstream_remote}/{upstream_branch}:deps.lock" > "$tmp/theirs.lock"

awk '
  FNR == 1 { file++ }
  file == 1 {
    base[$0] = 1
    next
  }
  file == 2 {
    ours[$0] = 1
    if ($0 ~ /^[[:space:]]*"/ && !($0 in base)) {
      add[++nadd] = $0
    }
    next
  }
  file == 3 {
    theirs[$0] = 1
    lines[++nlines] = $0
    next
  }
  END {
    insert_at = 0
    for (i = 1; i <= nlines; i++) {
      line = lines[i]
      if (line ~ /^[[:space:]]*"/ && (line in base) && (line in ours)) {
        insert_at = i
        break
      }
    }
    if (insert_at == 0) {
      for (i = 1; i <= nlines; i++) {
        line = lines[i]
        if (line ~ /^[[:space:]]*"/ && !((line in base) && !(line in ours))) {
          insert_at = i + 1
          break
        }
      }
    }
    for (i = 1; i <= nlines; i++) {
      if (i == insert_at) {
        for (j = 1; j <= nadd; j++) {
          if (!(add[j] in theirs)) print add[j]
        }
      }
      line = lines[i]
      if (line ~ /^[[:space:]]*"/ && (line in base) && !(line in ours)) {
        continue
      }
      print line
    }
    if (insert_at > nlines) {
      for (j = 1; j <= nadd; j++) {
        if (!(add[j] in theirs)) print add[j]
      }
    }
  }
' "$tmp/base.lock" "$tmp/ours.lock" "$tmp/theirs.lock" > "$tmp/merged.lock"

cp "$tmp/merged.lock" deps.lock
git add deps.lock
git commit --no-edit
